import 'package:flutter/foundation.dart';
import '../domain/repository_source.dart';
import '../domain/repository_storage.dart';
class RepositoryRegistry extends ChangeNotifier{RepositoryRegistry({RepositoryStorage? storage}):_storage=storage;final RepositoryStorage? _storage;final List<RepositorySource> _sources=[];bool _initialized=false;List<RepositorySource> get sources=>List.unmodifiable(_sources);bool get initialized=>_initialized;Future<void> initialize() async {if(_initialized)return;final s=_storage;if(s!=null){_sources..clear()..addAll(_deduplicated(await s.load()));}_initialized=true;notifyListeners();}Future<void> addUrl(String raw) async {final v=raw.trim();if(v.isEmpty)throw const FormatException('Informe a URL do repositório.');final u=Uri.tryParse(v);if(!_isHttpUri(u))throw const FormatException('Use uma URL HTTP ou HTTPS válida para o repositório.');await _addSource(RepositorySource(uri:u!,enabled:true));}Future<void> addResolvedEndpoint({required Uri infoUri,required Uri packageBaseUri,Uri? checksumUri,String? name}) async {if(!_isHttpUri(infoUri)||!_isHttpUri(packageBaseUri))throw const FormatException('O addon de repositório publicou um endpoint HTTP/HTTPS inválido.');await _addSource(RepositorySource(uri:infoUri,enabled:true,packageBaseUri:packageBaseUri,checksumUri:checksumUri,name:name));}Future<void> _addSource(RepositorySource s) async {if(_sources.any((e)=>e.uri==s.uri))throw const FormatException('Este repositório já foi adicionado.');_sources.add(s);await _persist();notifyListeners();}Future<void> remove(Uri u) async {final n=_sources.length;_sources.removeWhere((e)=>e.uri==u);if(n==_sources.length)return;await _persist();notifyListeners();}Future<void> setEnabled(Uri u,bool enabled) async {final i=_sources.indexWhere((e)=>e.uri==u);if(i<0||_sources[i].enabled==enabled)return;_sources[i]=_sources[i].copyWith(enabled:enabled);await _persist();notifyListeners();}Future<void> _persist() async {if(_storage!=null)await _storage!.save(sources);}List<RepositorySource> _deduplicated(List<RepositorySource> s){final seen=<Uri>{};return[for(final e in s)if(seen.add(e.uri))e];}bool _isHttpUri(Uri? u)=>u!=null&&(u.scheme=='http'||u.scheme=='https')&&u.host.isNotEmpty;}
